export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed ?? 4.0;
  const g = inputs.gravity ?? 9.8;
  const tTop = u / g;

  const tossedVelocity = u - g * time;
  const tossedAcceleration = -g;
  const tossedHeight = Math.max(0, u * time - 0.5 * g * time * time);

  let dropVelocity = 0;
  let dropAcceleration = 0;
  let dropHeight = (u * u) / (2 * g);

  if (time >= tTop) {
    const dt = time - tTop;
    dropVelocity = -g * dt;
    dropAcceleration = -g;
    dropHeight = Math.max(0, (u * u) / (2 * g) - 0.5 * g * dt * dt);
  }

  const laneY = 50;
  const laneW = 280;
  const laneH = 350;
  const tossX = 30;
  const dropX = 330;

  let tossState = 'At launch';
  if (time > 0 && time < tTop - 0.02) tossState = 'Rising';
  else if (Math.abs(time - tTop) <= 0.02) tossState = 'At the top';
  else if (time > tTop + 0.02 && tossedHeight > 0.001) tossState = 'Falling';
  else if (time > tTop && tossedHeight <= 0.001) tossState = 'At launch height';

  let dropState = 'Held in place';
  if (Math.abs(time - tTop) <= 0.02) dropState = 'Just released';
  else if (time > tTop + 0.02 && dropHeight > 0.001) dropState = 'Falling together';
  else if (time > tTop && dropHeight <= 0.001) dropState = 'At launch height';

  const objects = [];
  objects.push(...sdk.panel({ x: tossX, y: laneY, w: laneW, h: laneH, title: 'Toss', state: tossState, id: 'lane.toss' }));
  objects.push(...sdk.panel({ x: dropX, y: laneY, w: laneW, h: laneH, title: 'Drop', state: dropState, id: 'lane.drop' }));

  const axisY = laneY + laneH - 30;
  const axisH = 260;
  const pxPerM = axisH / 2.2;

  const tossAxisX = tossX + 45;
  const dropAxisX = dropX + 45;
  objects.push(sdk.axis('axis.toss', { x: tossAxisX, y: axisY, length: axisH, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: 'Height', unit: 'm' }));
  objects.push(sdk.axis('axis.drop', { x: dropAxisX, y: axisY, length: axisH, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: 'Height', unit: 'm' }));

  const gateY = axisY - ((u * u) / (2 * g)) * pxPerM;
  const gateOpen = time >= tTop;
  objects.push(...sdk.gate('gate', dropX + 160, gateY, { open: gateOpen, label: 'Release gate' }));

  const tossedPxY = axisY - tossedHeight * pxPerM;
  const dropPxY = axisY - dropHeight * pxPerM;

  const tossBallX = tossX + 160;
  const dropBallX = dropX + 160;

  objects.push(sdk.circle('ball.toss', tossBallX, tossedPxY, 24));
  objects.push(sdk.circle('ball.drop', dropBallX, dropPxY, 24));

  const vScale = 12;
  const aScale = 6;

  objects.push(...sdk.vector('vec.v.toss', { x: tossBallX - 18, y: tossedPxY }, { value: tossedVelocity, direction: 'up', scale: vScale, label: 'v' }));
  objects.push(...sdk.vector('vec.a.toss', { x: tossBallX + 18, y: tossedPxY }, { value: tossedAcceleration, direction: 'up', scale: aScale, label: 'a' }));

  objects.push(...sdk.vector('vec.v.drop', { x: dropBallX - 18, y: dropPxY }, { value: dropVelocity, direction: 'up', scale: vScale, label: 'v' }));
  objects.push(...sdk.vector('vec.a.drop', { x: dropBallX + 18, y: dropPxY }, { value: dropAcceleration, direction: 'up', scale: aScale, label: 'a' }));

  const tossCalloutLines = [`v: ${sdk.format(tossedVelocity, 2)} m/s`, `a: ${sdk.format(tossedAcceleration, 2)} m/s²`];
  const dropCalloutLines = [`v: ${sdk.format(dropVelocity, 2)} m/s`, `a: ${sdk.format(dropAcceleration, 2)} m/s²`];

  objects.push(...sdk.callout(tossBallX + 32, tossedPxY - 20, tossCalloutLines, { id: 'callout.toss' }));
  objects.push(...sdk.callout(dropBallX + 32, dropPxY - 20, dropCalloutLines, { id: 'callout.drop' }));

  const frame = sdk.frame(objects, {
    width: 640,
    height: 420,
    readouts: [
      { id: 'tossedVelocity', value: tossedVelocity },
      { id: 'tossedAcceleration', value: tossedAcceleration },
      { id: 'dropVelocity', value: dropVelocity },
      { id: 'dropAcceleration', value: dropAcceleration }
    ]
  });

  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime: tTop,
    apexHeight: (u * u) / (2 * g),
    tossedVelocity,
    tossedAcceleration,
    tossedHeight,
    dropVelocity,
    dropAcceleration,
    dropHeight
  };

  return { frame, quantities };
}
